static class LRUCache {
        Map<Integer, DoubleLinkNode> map;
        DoubleLinkNode head;
        DoubleLinkNode tail;
        int size;
        int capacity;
        public LRUCache(int capacity) {
            this.capacity = capacity;
            size = 0;
            map = new HashMap<>();
            head = new DoubleLinkNode();
            tail = new DoubleLinkNode();
            head.next = tail;
            tail.pre = head;
        }
        public int get(int key) {
            if (!map.containsKey(key)) {
                return -1;
            }
            DoubleLinkNode cur = map.get(key);
            cutNode(cur);
            moveToHead(cur);
            return cur.value;
        }

        private void cutNode(DoubleLinkNode cur) {
            if (cur.value == null) {
                return;
            }
            cur.pre.next = cur.next;
            cur.next.pre = cur.pre;
        }

        private void moveToHead(DoubleLinkNode cur) {
            cur.pre = head;
            cur.next = head.next;
            head.next.pre = cur;
            head.next = cur;
        }

        public void put(int key, int value) {
            if (map.containsKey(key)) {
                DoubleLinkNode cur = map.get(key);
                cur.key = key;
                cur.value = value;
                cutNode(cur);
                moveToHead(cur);
            } else {
                DoubleLinkNode cur = new DoubleLinkNode();
                moveToHead(cur);
                cur.key = key;
                cur.value = value;
                map.put(key, cur);
                size++;
                if (this.size > this.capacity) {
                    map.remove(tail.pre.key);
                    cutNode(tail.pre);
                    size--;
                }
            }
        }

        class DoubleLinkNode {
            DoubleLinkNode next;
            DoubleLinkNode pre;
            Integer key;
            Integer value;

